import re
from pathlib import Path

import pytest

from tests.app.bundle_check import pinned

# As `uv export` writes uv.lock's pins, with markers this Python always or never meets.
CONSTRAINTS = """\
# This file was autogenerated by uv via the following command:
#    uv export --locked --no-hashes --no-dev --extra app --no-emit-project
charset-normalizer==3.5.1
    # via requests
colorama==0.4.6 ; python_version < '3'
soupsieve==3.0.4 ; python_version >= '3'
soupsieve==2.10 ; python_version < '3'
"""


def app_packages(tmp_path: Path, versions: dict[str, str]) -> Path:
    """An app_packages folder that holds each distribution at its version."""
    packages = tmp_path / "app_packages"
    for name, version in versions.items():
        dist_info = packages / f"{name}-{version}.dist-info"
        dist_info.mkdir(parents=True)
        metadata = f"Metadata-Version: 2.1\nName: {name}\nVersion: {version}\n"
        (dist_info / "METADATA").write_text(metadata, encoding="utf-8")
    return packages


@pytest.fixture
def constraints(tmp_path: Path) -> Path:
    path = tmp_path / "constraints.txt"
    path.write_text(CONSTRAINTS, encoding="utf-8")
    return path


def test_pinned_counts_the_packages_at_their_locked_versions(
    tmp_path: Path, constraints: Path
) -> None:
    packages = app_packages(
        tmp_path,
        {"r3context": "0.6.10", "Charset_Normalizer": "3.5.1", "soupsieve": "3.0.4"},
    )
    assert pinned(packages, constraints) == 2


@pytest.mark.parametrize(
    ("name", "version", "problem"),
    [
        (
            "charset-normalizer",
            "3.6.0",
            "charset-normalizer 3.6.0: uv.lock pins ==3.5.1",
        ),
        ("soupsieve", "2.10", "soupsieve 2.10: uv.lock pins ==3.0.4"),
        ("colorama", "0.4.6", "colorama 0.4.6: uv.lock pins no version"),
        ("zipp", "4.1.0", "zipp 4.1.0: uv.lock pins no version"),
    ],
    ids=["another version", "the other python's", "pinned only elsewhere", "unlocked"],
)
def test_pinned_exits_on_a_package_at_a_version_uv_lock_does_not_pin_here(
    tmp_path: Path, constraints: Path, name: str, version: str, problem: str
) -> None:
    packages = app_packages(tmp_path, {name: version})
    with pytest.raises(SystemExit, match=re.escape(problem)):
        pinned(packages, constraints)
